// One item per (suburb x listingType), carrying config forward
const cfg = items[0].json;
const out = [];
const since = new Date(Date.now() - 26*60*60*1000).toISOString();
for (const s of cfg.SUBURBS) {
  for (const lt of cfg.LISTING_TYPES) {
