// Flatten Domain results -> one item per listing with agency identity
const out = [];
for (const item of items) {
  const cfg = item.json.cfg || $('Fan out suburbs').first().json.cfg;
  const suburb = item.json.suburb;
  const listingType = item.json.listingType;
  const body = item.json.body ?? item.json;
  const rows = Array.isArray(body) ? body : (body?.data ?? []);
  for (const row of rows) {
    const l = row.listing ?? row;
    if (!l) continue;
    const adv = l.advertiser ?? {};
    out.push({ json: {
      cfg,
      persona: listingType === 'Rent' ? 'pm' : 'sales_agent',
      suburb,
      listing_id: l.id ?? l.listingId ?? null,
      listing_url: l.id ? `https://www.domain.com.au/${l.id}` : (l.seoUrl ?? ''),
      headline: l.headline ?? '',
      agency_id: adv.id ?? null,
      agency_name: adv.name ?? 'Unknown agency',
      agent_name: (l.contacts && l.contacts[0] && l.contacts[0].name) ? l.contacts[0].name : null
    }});
  }
}
return out;

// Dedupe agencies seen in the last 90 days (workflow static data)
// + enforce daily cap from config. NOTE: authoritative dedupe/idempotency
// lives in the Octopus inbox — this is only a politeness pre-filter.
const staticData = $getWorkflowStaticData('global');
staticData.seenAgencies = staticData.seenAgencies || {};
const now = Date.now();
const NINETY_D = 90*24*60*60*1000;
for (const k of Object.keys(staticData.seenAgencies)) {
  if (now - staticData.seenAgencies[k] > NINETY_D) delete staticData.seenAgencies[k];
}
const cap = items[0]?.json?.cfg?.MAX_NEW_OUTREACH_PER_DAY ?? 5;
const byAgency = {};
for (const item of items) {
  const key = String(item.json.agency_id ?? item.json.agency_name);
  if (staticData.seenAgencies[key]) continue;
  if (!byAgency[key]) byAgency[key] = { ...item.json, listings: [] };
  byAgency[key].listings.push({ url: item.json.listing_url, headline: item.json.headline, suburb: item.json.suburb });
}
const fresh = Object.entries(byAgency).slice(0, cap);
const out = [];
for (const [key, val] of fresh) {
  staticData.seenAgencies[key] = now;
  out.push({ json: val });
}
return out;

// Merge agency office contact (published business contact only) into candidate
const out = [];
for (let i = 0; i < items.length; i++) {
  const cand = $('Dedupe + daily cap').all()[i]?.json ?? {};
  const ag = items[i].json.body ?? items[i].json ?? {};
  const details = ag.details ?? ag;
  out.push({ json: {
    ...cand,
    office_email: details.email ?? ag.email ?? null,
    office_phone: details.phone ?? ag.phone ?? null,
    office_address: (ag.profile && ag.profile.address) ? ag.profile.address : null
  }});
}
return out;

