// Parse LLM JSON safely and assemble the candidate
const out = [];
for (let i = 0; i < items.length; i++) {
  const cand = $('Merge office contact').all()[i]?.json ?? {};
  const resp = items[i].json;
  let draft = { subject: null, body: null };
  try {
    const text = resp.content?.[0]?.text ?? '';
    const jsonStr = text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1);
    draft = JSON.parse(jsonStr);
  } catch (e) { draft = { subject: 'DRAFT PARSE FAILED', body: String(resp.content?.[0]?.text ?? '') }; }
  out.push({ json: { ...cand, draft } });
}
return out;

// Build the CANONICAL candidate payload (contract v1.1) and sign it.
// HMAC-SHA256 over `${timestamp}.${nonce}.${bodyString}` with the shared secret.
// Requires n8n env: NODE_FUNCTION_ALLOW_BUILTIN=crypto
const crypto = require('crypto');
const out = [];
for (const item of items) {
  const c = item.json;
  const hasContact = !!(c.office_email || c.office_phone);
  const payload = {
    schema_version: '1.1',
    idempotency_key: 'domain:agency:' + (c.agency_id ?? c.agency_name),
    candidate_type: 'public_b2b',
    source: {
      channel: 'domain_listing',
      source_id: c.cfg.SOURCE_ID,
      external_id: String(c.agency_id ?? c.agency_name),
      source_url: (c.listings && c.listings[0]) ? c.listings[0].url : null,
      received_at: new Date().toISOString()
    },
    contact: {
      name: c.agent_name,
      organisation: c.agency_name,
      phone: c.office_phone,
      email: c.office_email,
      preferred_channel: 'email'
    },
    consent: {
      basis: hasContact ? 'inferred_business' : 'none',
      evidence: hasContact ? 'office_contact_conspicuously_published_on_listing_or_agency_profile' : null,
      captured_at: new Date().toISOString(),
      outreach_allowed: hasContact,
      retention_class: 'b2b_prospect_12m',
      compliance_reason: 'SpamAct_inferred_consent_b2b_role_relevant'
    },
    property: { address: null, suburb: c.suburb, postcode: null, property_type: null },
    request: {
      service: c.persona === 'pm' ? 'end_of_lease_maintenance' : 'pre_sale_refresh',
      scope_text: (c.listings || []).map(l => l.headline + ' ' + l.url).join(' | '),
      urgency: 'standard', budget_aud: null, photos: []
    },
    payload_extra: { persona: c.persona, draft: c.draft, listings: c.listings },
    workflow: { status: 'received', owner_action_required: true, external_send_allowed: false, next_action: 'qualify' }
  };
  const body = JSON.stringify(payload);
  const timestamp = String(Math.floor(Date.now() / 1000));
  const nonce = crypto.randomUUID();
  const signature = crypto.createHmac('sha256', c.cfg.OCTOPUS_INBOX_HMAC_SECRET)
    .update(`${timestamp}.${nonce}.${body}`).digest('hex');
  out.push({ json: {
    OCTOPUS_BASE_URL: c.cfg.OCTOPUS_BASE_URL,
    body, timestamp, nonce, signature,
    idempotency_key: payload.idempotency_key,
    source_id: c.cfg.SOURCE_ID
  }});
}
return out;
